<?php namespace Workspace; ?>
<div class="oss-guest"><header class="panel inset"><h1>Кабинет contributor</h1><p><?= h($contributor['display_name']) ?> · <?= h($contributor['upstream']) ?></p><p><a href="<?= h(url('oss.public',['slug'=>$contributor['slug']])) ?>">Публичная витрина</a></p><form method="post"><?php formFields('oss.logout') ?><button class="secondary">Выйти</button></form></header>
<section class="panel inset"><h2>Предложить вклад</h2><form method="post" class="stack"><?php formFields('oss.submit') ?><label>Название<input name="title" required maxlength="180"></label><label>Ссылка на issue/PR настроенного GitHub<input type="url" name="upstream_url" maxlength="220" required></label><label>Описание<textarea name="body" maxlength="4000" required></textarea></label><button class="primary">Отправить на triage</button></form></section>
<section class="panel inset"><h2>Мои вклады</h2><?php if (!$rows): ?><p>Нет зарегистрированных вкладов.</p><?php endif ?><?php foreach ($rows as $r): ?><div class="splitrow"><a href="<?= h(url('oss.contributor',['id'=>$r['id'],'n'=>$page])) ?>"><?= h($r['title']) ?></a><span><?= h(OSS_STATES[$r['state']]) ?></span></div><?php endforeach ?></section>
<?php if ($selected): ?><section class="panel inset"><h2><?= h($selected['title']) ?></h2><p><?= h(OSS_STATES[$selected['state']]) ?> · <a href="<?= h($selected['upstream_url']) ?>" rel="noopener noreferrer">Upstream</a></p><p class="criteria-text"><?= h($selected['body']) ?></p><h3>Обсуждение (последние 200 сообщений)</h3><?php foreach ($comments as $msg): ?><div class="panel inset"><b><?= h($msg['author_kind']) ?></b> · <?= h(gmdate('Y-m-d H:i',(int)$msg['created_at'])) ?> UTC<p class="criteria-text"><?= h($msg['body']) ?></p></div><?php endforeach ?><form method="post" class="stack"><?php formFields('oss.reply') ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><label>Сообщение<textarea name="body" maxlength="4000" required></textarea></label><button class="primary">Ответить</button></form></section><?php endif ?>
<nav aria-label="Страницы вкладов"><?php if ($page>1): ?><a href="<?= h(url('oss.contributor',['n'=>$page-1])) ?>">← Предыдущая</a><?php endif ?> <?php if ($more): ?><a href="<?= h(url('oss.contributor',['n'=>$page+1])) ?>">Следующая →</a><?php endif ?></nav></div>
